import { expect, expectStatus, test, type Document, type Extraction, type Vendor } from "../../fixtures";

test("approving the replacement w9 approves a vendor whose other documents were already approved", { tag: "@LIF-06" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor in review; the reviewer approves two documents and rejects the w9.
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const { vendor, extractions } = await factory.vendorInReview();

  await expectStatus(
    await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, { data: { decision: "approve" } }),
    200,
  );
  await expectStatus(
    await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, { data: { decision: "approve" } }),
    200,
  );
  await expectStatus(
    await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
      data: { decision: "reject", note: "Legal name does not match" },
    }),
    200,
  );

  // Arrange: the member replaces the w9, waits for its extraction, and resubmits the vendor.
  const replacement = await factory.upload(vendor.id, "w9", "w9.txt", "member");
  await expect
    .poll(
      async () => (await expectStatus<Document>(await member.get(`/api/documents/${replacement.id}`), 200)).status,
      { message: "replacement w9 finishes extraction", timeout: 30_000 },
    )
    .toBe("extracted");
  const resubmitted = await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  expect(resubmitted.status).toBe("in_review");
  const replacementExtraction = await factory.extraction(replacement.id, "reviewer");
  expect(replacementExtraction.status).toBe("pending_review");

  // Act: the reviewer approves the replacement w9's extraction.
  const response = await reviewer.post(`/api/extractions/${replacementExtraction.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert: the decision is stored, the vendor is approved, and the audit trail records it.
  const decided = await expectStatus<Extraction>(response, 200);
  expect(decided.status).toBe("approved");

  const stored = await expectStatus<Vendor>(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.status).toBe("approved");

  const trail = await expectStatus<{ items: { action: string }[] }>(
    await reviewer.get(`/api/vendors/${vendor.id}/audit`),
    200,
  );
  expect(trail.items.map((event) => event.action)).toContain("vendor.approved");
});
